      /* RULES */
      'rules.subtitle': 'C&oacute;mo Funciona', 'rules.h2': 'Reglas de Reserva y Estad&iacute;a',
      'rules.p': 'Reglas simples y justas que hacen funcionar perfectamente la propiedad compartida.',
      'rules.r1.h4': 'Estad&iacute;a M&iacute;nima de 2 Noches', 'rules.r1.p': 'Todas las reservas requieren un m&iacute;nimo de 2 noches para garantizar una experiencia de calidad.',
