      /* MAINTENANCE */
      'maint.subtitle': 'Mantenimiento', 'maint.h2': 'Costos Anuales Transparentes',
      'maint.p': '$100 por acci&oacute;n por a&ntilde;o &mdash; fondo total de $8.000. Mantiene El Nido prístino y funcionando sin problemas.',
      'maint.c1.h3': '&#x1f4b5; Qu&eacute; Incluye', 'maint.c1.sub': '$100/acci&oacute;n/a&ntilde;o &mdash; fondo total de $8.000 (80 acciones)',
      'maint.c1.li1': 'Suministro de agua', 'maint.c1.li2': 'Internet Starlink de alta velocidad', 'maint.c1.li3': 'Jard&iacute;n una vez al mes', 'maint.c1.li4': 'Reparaciones y mantenimiento b&aacute;sico',
