      /* GOVERNANCE */
      'gov.subtitle': 'Gobernanza', 'gov.h2': 'Democracia en la Blockchain',
      'gov.p': 'Cada acci&oacute;n es un voto. Todas las decisiones son transparentes, registradas en cadena y aplicadas por contratos inteligentes.',
      'gov.g1.h4': 'Ingreso de Nuevos Miembros', 'gov.g1.p': 'Requiere voto mayoritario de los miembros existentes. La comunidad elige qui&eacute;n se une.',
      'gov.g2.h4': 'Valorización de Acciones', 'gov.g2.p': 'Se espera que los precios de las acciones aumenten ~10%/a&ntilde;o, reflejando mejoras a la propiedad y apreciaci&oacute;n del mercado.',
      'gov.g3.h4': 'Nuevas Evaluaciones', 'gov.g3.p': 'Requieren voto mayoritario para ser aprobadas. Una vez aprobadas, son obligatorias para todos los miembros.',
